filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
	if err != nil {
		return err
	}
	if entry.IsDir() {
		if entry.Name() == ".git" || entry.Name() == "node_modules" {
			return filepath.SkipDir
		}
		return nil
	}
	ext := strings.ToLower(filepath.Ext(path))
	if ext != ".css" && ext != ".scss" && ext != ".less" {
		return nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%s is not UTF-8", path)
	}
	texts = append(texts, string(data))
	files[ext]++
	return nil
})

filepath.WalkDir(root, func(path string, entry fs.DirEntry, err error) error {
	if err != nil {
		return err
	}
	if entry.IsDir() && entry.Name() == ".git" {
		return filepath.SkipDir
	}
	if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
		return nil
	}
	encoded, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	if !utf8.Valid(encoded) {
		return fmt.Errorf("non-UTF-8 corpus file %s: decoding needs its own oracle", path)
	}
	relative, err := filepath.Rel(root, path)
	if err != nil {
		return err
	}
	relative = filepath.ToSlash(relative)
	group := "Adamic"
	if strings.HasPrefix(relative, "cohere/") {
		group = "cohere"
	}
	if strings.HasPrefix(relative, "cohere/TypeScript/") {
		group = "TypeScript"
	}
	groups[group]++
	cases = append(cases, textCase{relative, string(encoded)})
	return nil
})

